#pragma once
#include <stdint.h>
void motorsInit();
void motorsEnable(bool en);
void motorsSet(int left, int right, float vbat); // -255..255 requested @nominal V
void motorsStop();

#include "motors.h"
#include "config.h"

static int curL = 0, curR = 0;

void motorsInit() {
  pinMode(PIN_STBY, OUTPUT); digitalWrite(PIN_STBY, LOW);
  uint8_t p[] = {PIN_PWMA, PIN_AIN1, PIN_AIN2, PIN_PWMB, PIN_BIN1, PIN_BIN2};
  for (uint8_t i = 0; i < 6; i++) { pinMode(p[i], OUTPUT); digitalWrite(p[i], LOW); }
}

void motorsEnable(bool en) { digitalWrite(PIN_STBY, en ? HIGH : LOW); }

static void drive(uint8_t pwm, uint8_t in1, uint8_t in2, int v, bool inv) {
  bool fwd = v >= 0; if (inv) fwd = !fwd;
  digitalWrite(in1, fwd ? HIGH : LOW);
  digitalWrite(in2, fwd ? LOW : HIGH);
  analogWrite(pwm, abs(v));
}

static int ramp(int cur, int tgt) {
  if (tgt > cur + RAMP_STEP) return cur + RAMP_STEP;
  if (tgt < cur - RAMP_STEP) return cur - RAMP_STEP;
  return tgt;
}

void motorsSet(int left, int right, float vbat) {
  float k = (vbat > 5.0f) ? VBAT_NOMINAL / vbat : 1.0f; // battery compensation
  int l = constrain((int)(left * k), -PWM_MAX, PWM_MAX);
  int r = constrain((int)(right * k), -PWM_MAX, PWM_MAX);
  curL = ramp(curL, l); curR = ramp(curR, r);
  drive(PIN_PWMA, PIN_AIN1, PIN_AIN2, curL, LEFT_INVERT);
  drive(PIN_PWMB, PIN_BIN1, PIN_BIN2, curR, RIGHT_INVERT);
}

void motorsStop() {
  curL = curR = 0;
  analogWrite(PIN_PWMA, 0); analogWrite(PIN_PWMB, 0);
  // short brake
  digitalWrite(PIN_AIN1, HIGH); digitalWrite(PIN_AIN2, HIGH);
  digitalWrite(PIN_BIN1, HIGH); digitalWrite(PIN_BIN2, HIGH);
}

#pragma once
#include <stdint.h>
enum Button { BTN_NONE, BTN_GO, BTN_CAL };
void sensorsInit();
void sensorsCalibrateStep();
void sensorsResetCalibration();
bool sensorsCalibrated();
// returns true if line visible; pos 0..7000
bool sensorsReadLine(uint16_t &pos);
float batteryRead();       // filtered volts
Button buttonEvent();      // debounced press edge
void sensorsDump();

#include "sensors.h"
#include "config.h"
#include <QTRSensors.h>

static QTRSensors qtr;
static uint16_t vals[8];
static bool calibrated = false;
static float vbatF = 0;

void sensorsInit() {
  qtr.setTypeRC();
  qtr.setSensorPins(QTR_PINS, 8);
  qtr.setEmitterPin(PIN_QTR_LEDON);
  qtr.setTimeout(QTR_TIMEOUT_US);
  vbatF = analogRead(PIN_VBAT) * VBAT_SCALE;
}

void sensorsResetCalibration() { qtr.resetCalibration(); calibrated = false; }
void sensorsCalibrateStep() { qtr.calibrate(); calibrated = true; }
bool sensorsCalibrated() { return calibrated; }

bool sensorsReadLine(uint16_t &pos) {
  pos = qtr.readLineBlack(vals); // keeps last side when lost
  uint16_t mx = 0;
  for (uint8_t i = 0; i < 8; i++) if (vals[i] > mx) mx = vals[i];
  return mx > LINE_THRESHOLD;
}

float batteryRead() {
  float v = analogRead(PIN_VBAT) * VBAT_SCALE;
  vbatF += 0.1f * (v - vbatF);
  if (v < VBAT_NOBATT) vbatF = v; // react instantly to battery removal
  return vbatF;
}

Button buttonEvent() {
  static Button stable = BTN_NONE, last = BTN_NONE;
  static uint32_t t = 0;
  int a = analogRead(PIN_BUTTONS);
  Button b = a > BTN_NONE_TH ? BTN_NONE : (a < BTN_CAL_TH ? BTN_CAL : BTN_GO);
  if (b != last) { last = b; t = millis(); }
  if (millis() - t >= BTN_DEBOUNCE_MS && b != stable) {
    stable = b;
    if (b != BTN_NONE) return b;
  }
  return BTN_NONE;
}

void sensorsDump() {
  Serial.print(F("CAL min/max:"));
  for (uint8_t i = 0; i < 8; i++) {
    Serial.print(' '); Serial.print(qtr.calibrationOn.minimum[i]);
    Serial.print('/'); Serial.print(qtr.calibrationOn.maximum[i]);
  }
  Serial.println();
}

// LineDart firmware: PID line follower, Arduino Nano + TB6612 + QTR-8RC
#include <Arduino.h>
#include "config.h"
#include "motors.h"
#include "sensors.h"

enum State { IDLE, CALIBRATING, RUNNING, LOWBATT };
static State state = IDLE;
static uint32_t stateT = 0, lastSeen = 0, lastLoop = 0, lastTele = 0, lastBat = 0;
static float integ = 0, lastErr = 0, vbat = 0;
static int lastSide = 0; // -1 left, +1 right
static uint8_t lowCnt = 0;

static void enter(State s) {
  state = s; stateT = millis();
  if (s != RUNNING && s != CALIBRATING) { motorsStop(); motorsEnable(false); }
  Serial.print(F("STATE "));
  Serial.println(s == IDLE ? F("IDLE") : s == CALIBRATING ? F("CAL") : s == RUNNING ? F("RUN") : F("LOWBATT"));
}

static bool batteryOk() { return vbat >= VBAT_RESUME; }

static void updateLed() {
  uint32_t t = millis();
  bool on;
  switch (state) {
    case IDLE: on = sensorsCalibrated() ? true : ((t / 1000) % 2); break; // solid if ready, slow blink if not
    case CALIBRATING: on = (t / 100) % 2; break;  // fast blink
    case RUNNING: on = (t / 250) % 2; break;      // medium blink
    default: on = (t % 1000) < 80; break;         // short flash = low battery / no battery
  }
  digitalWrite(PIN_LED, on);
}

static void runPid(uint32_t now) {
  uint16_t pos;
  bool seen = sensorsReadLine(pos);
  float err = (float)pos - 3500.0f;
  if (seen) {
    lastSeen = now;
    if (err < -1500) lastSide = -1; else if (err > 1500) lastSide = 1;
    integ = constrain(integ + err, -I_LIMIT, I_LIMIT);
    float corr = KP * err + KI * integ + KD * (err - lastErr);
    lastErr = err;
    // line to the right (pos>3500) -> turn right: speed up left
    int base = BASE_SPEED;
    if (fabs(err) > 2500) base = BASE_SPEED / 2; // slow down in sharp corners
    motorsSet(base + (int)corr, base - (int)corr, vbat);
    return;
  }
  uint32_t lost = now - lastSeen;
  if (lost > LOST_STOP_MS) { Serial.println(F("Line lost - stop")); enter(IDLE); return; }
  if (lost > LOST_DELAY_MS) {
    int s = lastSide ? lastSide : 1;
    motorsSet(s * SEARCH_SPEED, -s * SEARCH_SPEED, vbat); // pivot toward last seen side
  } else {
    // brief gap: keep last-seen hard turn
    int s = lastSide;
    motorsSet(BASE_SPEED / 2 + s * 80, BASE_SPEED / 2 - s * 80, vbat);
  }
}

void setup() {
  motorsInit();           // STBY low first
  pinMode(PIN_LED, OUTPUT);
  Serial.begin(115200);
  sensorsInit();
  for (uint8_t i = 0; i < 20; i++) { vbat = batteryRead(); delay(5); }
  Serial.println(F("LineDart ready. CAL=calibrate, GO=start/stop"));
  enter(IDLE);
}

void loop() {
  uint32_t now = millis();
  if (now - lastBat >= 10) {
    lastBat = now; vbat = batteryRead();
    if (vbat < VBAT_CUTOFF) { if (lowCnt < 255) lowCnt++; } else lowCnt = 0;
    if ((lowCnt >= VBAT_LOW_COUNT || vbat < VBAT_NOBATT) && state != LOWBATT && state != IDLE) enter(LOWBATT);
    if (state == IDLE && lowCnt >= VBAT_LOW_COUNT) enter(LOWBATT);
    if (state == LOWBATT && batteryOk()) enter(IDLE);
  }

  Button b = buttonEvent();
  switch (state) {
    case IDLE:
      if (b == BTN_CAL) {
        if (vbat < VBAT_NOBATT) { Serial.println(F("No battery (USB only)")); break; }
        sensorsResetCalibration(); motorsEnable(true); enter(CALIBRATING);
      } else if (b == BTN_GO) {
        if (!sensorsCalibrated()) Serial.println(F("Calibrate first"));
        else if (!batteryOk()) Serial.println(F("Battery too low"));
        else { integ = 0; lastErr = 0; lastSeen = now; motorsEnable(true); enter(RUNNING); }
      }
      break;
    case CALIBRATING: {
      sensorsCalibrateStep();
      uint32_t e = now - stateT;
      // spin one way then the other so the array sweeps the line both directions
      int s = (e < CAL_TIME_MS / 4 || e > 3 * CAL_TIME_MS / 4) ? 1 : -1;
      motorsSet(s * CAL_SPEED, -s * CAL_SPEED, vbat);
      if (e >= CAL_TIME_MS) { enter(IDLE); sensorsDump(); }
      break;
    }
    case RUNNING:
      if (b == BTN_GO || b == BTN_CAL) { enter(IDLE); break; }
      if (micros() - lastLoop >= LOOP_US) { lastLoop = micros(); runPid(now); }
      break;
    case LOWBATT:
      break;
  }

  if (now - lastTele >= 200) {
    lastTele = now;
    Serial.print(F("vbat=")); Serial.print(vbat, 2);
    Serial.print(F(" err=")); Serial.println(lastErr, 0);
  }
  updateLed();
}
